{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of abstract structures, quantities, and patterns through rigorous logical reasoning." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Analysis and practice of written and oral communication, literature, and critical theory." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Associate Professor of Computer Science", Bio = "Dr. Chen specializes in machine learning and distributed systems. She has published over 40 peer-reviewed papers and holds two patents in real-time data processing.", Email = "achen@university.edu", DepartmentId = 1 },
            new() { Id = 2, Name = "Dr. Robert Singh", Title = "Professor of Mathematics", Bio = "Dr. Singh is a leading researcher in combinatorics and graph theory. He has received the National Science Foundation CAREER Award and mentors undergraduate research projects.", Email = "rsingh@university.edu", DepartmentId = 2 },
            new() { Id = 3, Name = "Dr. Maria Lopez", Title = "Assistant Professor of English", Bio = "Dr. Lopez focuses on contemporary American literature and digital humanities. She is the author of two books on narrative form in the 21st century.", Email = "mlopez@university.edu", DepartmentId = 3 },
            new() { Id = 4, Name = "Dr. James Okafor", Title = "Professor of Physics", Bio = "Dr. Okafor conducts research in quantum optics and photonics. He leads the university's Photonics Lab and has secured several multi-year federal grants.", Email = "jokafor@university.edu", DepartmentId = 4 }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "An introductory course covering fundamental programming concepts using Python, including variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of core data structures such as lists, trees, graphs, and hash tables, along with algorithm design and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 1, InstructorId = 1, IsFeatured = false },
            new() { Id = 3, Title = "Operating Systems", Code = "CS 310", Description = "Exploration of process management, memory allocation, file systems, and concurrency in modern operating systems.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 1, InstructorId = 1, IsFeatured = false },

            // Mathematics
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions with applications in science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", DepartmentId = 2, InstructorId = 2, IsFeatured = false },
            new() { Id = 6, Title = "Probability and Statistics", Code = "MATH 360", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = 2, InstructorId = 2, IsFeatured = false },

            // English
            new() { Id = 7, Title = "College Composition", Code = "ENG 101", Description = "Development of analytical reading and academic writing skills through essay composition and peer review.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 8, Title = "American Literature", Code = "ENG 250", Description = "Survey of major works in American literature from the colonial period to the present, with attention to cultural and historical context.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", DepartmentId = 3, InstructorId = 3, IsFeatured = false },
            new() { Id = 9, Title = "Creative Writing Workshop", Code = "ENG 315", Description = "A workshop-style course in fiction and poetry writing, emphasizing craft, revision, and constructive critique.", Credits = 3, Schedule = "Fri 1:00–3:45 PM", DepartmentId = 3, InstructorId = 3, IsFeatured = false },

            // Physics
            new() { Id = 10, Title = "General Physics I", Code = "PHYS 201", Description = "Mechanics, thermodynamics, and waves with calculus-based problem solving and laboratory exercises.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", DepartmentId = 4, InstructorId = 4, IsFeatured = true },
            new() { Id = 11, Title = "Electromagnetism", Code = "PHYS 301", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and circuit theory.", Credits = 3, Schedule = "Tue/Thu 10:00–11:15 AM", DepartmentId = 4, InstructorId = 4, IsFeatured = false },
            new() { Id = 12, Title = "Quantum Mechanics", Code = "PHYS 410", Description = "Introduction to wave-particle duality, the Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 4, InstructorId = 4, IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetCourses() => _courses;

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public Instructor? GetInstructorById(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

