@page "/courses"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" class="search-form">
    <div class="search-controls">
        <input type="text" name="Search" value="@Search" placeholder="Search courses..." class="form-input" />
        <select name="DepartmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
        <button type="submit" class="btn-primary">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.SearchCourses(Search, DepartmentId);
}

@if (!courses.Any())
{
    <p class="no-results">No courses found.</p>
}
else
{
    <table class="course-table">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td><a href="/courses/@course.Id">@course.Title</a></td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

@{
    var course = CatalogService.GetCourseById(Id);
}

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="/courses">Back to Courses</a>
}
else
{
    var department = CatalogService.GetDepartmentById(course.DepartmentId);
    var instructor = CatalogService.GetInstructorById(course.InstructorId);

    <PageTitle>@course.Title - University Course Catalog</PageTitle>

    <div class="course-detail">
        <a href="/courses" class="back-link">&larr; Back to Courses</a>

        <h1>@course.Code: @course.Title</h1>
        <p class="course-description">@course.Description</p>

        <div class="detail-grid">
            <div class="detail-item">
                <strong>Credits</strong>
                <span>@course.Credits</span>
            </div>
            <div class="detail-item">
                <strong>Schedule</strong>
                <span>@course.Schedule</span>
            </div>
            <div class="detail-item">
                <strong>Department</strong>
                <span><a href="/courses?DepartmentId=@department?.Id">@department?.Name</a></span>
            </div>
        </div>

        @if (instructor is not null)
        {
            <div class="instructor-card">
                <h2>Instructor</h2>
                <h3>@instructor.Name</h3>
                <p class="instructor-title">@instructor.Title</p>
                <p>@instructor.Bio</p>
                <p><a href="mailto:@instructor.Email">@instructor.Email</a></p>
            </div>
        }

        <div class="enroll-action">
            <a href="/enroll?CourseId=@course.Id" class="btn-primary-link">Enroll in This Course</a>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Course Enrollment</h1>

@if (Submitted)
{
    <div class="confirmation-message">
        <h2>Enrollment Request Submitted!</h2>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
        <strong>@(CatalogService.GetCourseById(Model.CourseId)?.Title)</strong> has been received.</p>
        <p>Student ID: @Model.StudentId</p>
        <p>Submitted at: @Model.SubmittedAt.ToString("f")</p>
        <a href="/courses" class="btn-primary-link">Browse More Courses</a>
    </div>
}
else
{
    <EditForm Model="Model" method="post" FormName="EnrollForm" OnValidSubmit="HandleSubmit">
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="studentName">Student Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-input" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-input" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn-primary">Submit Enrollment</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Model.SubmittedAt = DateTime.Now;
        CatalogService.SubmitEnrollment(Model);
        Submitted = true;
    }
}

