 @page "/enroll"
 @using UniversityCourseCatalog.Models
 @using UniversityCourseCatalog.Services
 @inject CatalogService CatalogService

 <PageTitle>Enroll - University Course Catalog</PageTitle>

 <h1>Course Enrollment</h1>

 @if (Submitted)
 {
     <div class="confirmation-message">
         <h2>Enrollment Request Submitted!</h2>
         <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
         <strong>@(CatalogService.GetCourseById(Model.CourseId)?.Title)</strong> has been received.</p>
         <p>Student ID: @Model.StudentId</p>
         <p>Submitted at: @Model.SubmittedAt.ToString("f")</p>
         <a href="/courses" class="btn-primary-link">Browse More Courses</a>
     </div>
 }
 else
 {
     <EditForm Model="Model" method="post" FormName="EnrollForm" OnValidSubmit="HandleSubmit">
         <AntiforgeryToken />
         <DataAnnotationsValidator />
         <ValidationSummary />

         <div class="form-group">
             <label for="studentName">Student Name</label>
             <InputText id="studentName" @bind-Value="Model.StudentName" class="form-input" />
             <ValidationMessage For="() => Model.StudentName" />
         </div>

         <div class="form-group">
             <label for="studentId">Student ID</label>
             <InputText id="studentId" @bind-Value="Model.StudentId" class="form-input" />
             <ValidationMessage For="() => Model.StudentId" />
         </div>

         <div class="form-group">
             <label for="courseId">Course</label>
             <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                 <option value="0">-- Select a Course --</option>
                 @foreach (var course in CatalogService.GetCourses())
                 {
                     <option value="@course.Id">@course.Code - @course.Title</option>
                 }
             </InputSelect>
             <ValidationMessage For="() => Model.CourseId" />
         </div>

         <button type="submit" class="btn-primary">Submit Enrollment</button>
     </EditForm>
 }

 @code {
     [SupplyParameterFromForm]
     public EnrollmentRequest? Model { get; set; }

     protected override void OnInitialized()
     {
         Model ??= new();
         if (CourseId.HasValue && Model.CourseId == 0)
         {
             Model.CourseId = CourseId.Value;
         }
     }

     [SupplyParameterFromQuery]
     public int? CourseId { get; set; }

     private bool Submitted { get; set; }

     private void HandleSubmit()
     {
         Model.SubmittedAt = DateTime.Now;
         CatalogService.SubmitEnrollment(Model);
         Submitted = true;
     }
 }

