 @page "/courses"
 @using UniversityCourseCatalog.Services
 @inject CatalogService CatalogService

 <PageTitle>Courses - University Course Catalog</PageTitle>

 <h1>Course Catalog</h1>

 <form method="get" class="search-form">
     <div class="search-controls">
         <input type="text" name="Search" value="@Search" placeholder="Search courses..." class="form-input" />
         <select name="DepartmentId" class="form-select">
             <option value="">All Departments</option>
             @foreach (var dept in CatalogService.GetDepartments())
             {
                 <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
             }
         </select>
         <button type="submit" class="btn-primary">Search</button>
     </div>
 </form>

 @{
     var courses = CatalogService.SearchCourses(Search, DepartmentId);
 }

 @if (!courses.Any())
 {
     <p class="no-results">No courses found.</p>
 }
 else
 {
     <table class="course-table">
         <thead>
             <tr>
                 <th>Code</th>
                 <th>Title</th>
                 <th>Credits</th>
                 <th>Schedule</th>
                 <th></th>
             </tr>
         </thead>
         <tbody>
             @foreach (var course in courses)
             {
                 <tr>
                     <td>@course.Code</td>
                     <td><a href="/courses/@course.Id">@course.Title</a></td>
                     <td>@course.Credits</td>
                     <td>@course.Schedule</td>
                     <td><a href="/courses/@course.Id">Details</a></td>
                 </tr>
             }
         </tbody>
     </table>
 }

 @code {
     [SupplyParameterFromQuery]
     public string? Search { get; set; }

     [SupplyParameterFromQuery]
     public int? DepartmentId { get; set; }
 }

