 @page "/courses/{Id:int}"
 @using UniversityCourseCatalog.Services
 @inject CatalogService CatalogService

 @{
     var course = CatalogService.GetCourseById(Id);
 }

 @if (course is null)
 {
     <PageTitle>Course Not Found</PageTitle>
     <h1>Course Not Found</h1>
     <p>The requested course could not be found.</p>
     <a href="/courses">Back to Courses</a>
 }
 else
 {
     var department = CatalogService.GetDepartmentById(course.DepartmentId);
     var instructor = CatalogService.GetInstructorById(course.InstructorId);

     <PageTitle>@course.Title - University Course Catalog</PageTitle>

     <div class="course-detail">
         <a href="/courses" class="back-link">&larr; Back to Courses</a>

         <h1>@course.Code: @course.Title</h1>
         <p class="course-description">@course.Description</p>

         <div class="detail-grid">
             <div class="detail-item">
                 <strong>Credits</strong>
                 <span>@course.Credits</span>
             </div>
             <div class="detail-item">
                 <strong>Schedule</strong>
                 <span>@course.Schedule</span>
             </div>
             <div class="detail-item">
                 <strong>Department</strong>
                 <span><a href="/courses?DepartmentId=@department?.Id">@department?.Name</a></span>
             </div>
         </div>

         @if (instructor is not null)
         {
             <div class="instructor-card">
                 <h2>Instructor</h2>
                 <h3>@instructor.Name</h3>
                 <p class="instructor-title">@instructor.Title</p>
                 <p>@instructor.Bio</p>
                 <p><a href="mailto:@instructor.Email">@instructor.Email</a></p>
             </div>
         }

         <div class="enroll-action">
             <a href="/enroll?CourseId=@course.Id" class="btn-primary-link">Enroll in This Course</a>
         </div>
     </div>
 }

 @code {
     [Parameter]
     public int Id { get; set; }
 }

